            # Scan memory regions with enhanced force reading
            for region in memory_regions:
                # Skip non-committed memory
                if not (region['State'] & 0x1000):  # MEM_COMMIT
                    continue

                # Skip regions that are too small
                if region['RegionSize'] < 1024:
